import { Elysia, t } from "elysia";
import { cors } from "@elysiajs/cors";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

const app = new Elysia()
  .use(cors({ origin: ["http://localhost:3000"] }))
  .get("/", () => "Welcome to Smart Repair API")
  .get("/api/tickets", () => {
    return prisma.ticket.findMany({
      orderBy: { createdAt: "desc" },
    });
  })
  .get("/api/analytics", async () => {
    const total = await prisma.ticket.count();
    const done = await prisma.ticket.count({ where: { status: "done" } });
    const urgent = await prisma.ticket.count({ where: { priority: "urgent" } });
    const inProgress = await prisma.ticket.count({ where: { status: "in-progress" } });

    const todo = total - done - inProgress;

    // 为图表提供分布数据
    const distribution = [
      { name: "待处理", value: todo, fill: "#71717a" }, // zinc-500
      { name: "维修中", value: inProgress, fill: "#3b82f6" }, // blue-500
      { name: "已完成", value: done, fill: "#22c55e" }, // green-500
    ].filter(item => item.value > 0);

    return {
      total,
      done,
      urgent,
      inProgress,
      completionRate: total === 0 ? 0 : Math.round((done / total) * 100),
      distribution
    };
  })
  .post("/api/login", async ({ body }) => {
    const { username, password } = body;
    if (username === "admin" && password === "admin123") {
      return { success: true, token: "admin-jwt-token", role: "admin", name: "Admin" };
    }
    return new Response(JSON.stringify({ error: "账号或密码错误" }), { status: 401 });
  }, {
    body: t.Object({
      username: t.String(),
      password: t.String()
    })
  })
  .post("/api/tickets", async ({ body }) => {
    const { title, description } = body;

    const urgentKeywords = ["碎", "不亮", "冒烟", "坏"];
    const isUrgent = urgentKeywords.some(keyword => description.includes(keyword));
    const priority = isUrgent ? "urgent" : "normal";

    return prisma.ticket.create({
      data: {
        title,
        description,
        priority,
        status: "todo",
      },
    });
  }, {
    body: t.Object({
      title: t.String({ minLength: 1, error: "标题不能为空" }),
      description: t.String({ minLength: 1, error: "描述不能为空" })
    })
  })
  .patch("/api/tickets/:id", async ({ params: { id }, body }) => {
    const { status } = body;
    return prisma.ticket.update({
      where: { id: Number(id) },
      data: { status },
    });
  }, {
    body: t.Object({
      status: t.String()
    })
  })
  .delete("/api/tickets/clear-done", async () => {
    return prisma.ticket.deleteMany({
      where: { status: "done" },
    });
  })
  .delete("/api/tickets/:id", async ({ params: { id } }) => {
    return prisma.ticket.delete({
      where: { id: Number(id) },
    });
  })
  .listen(8080);

console.log(
  ` Elysia is running at ${app.server?.hostname}:${app.server?.port}`
);

import { Elysia, t } from "elysia";
import { cors } from "@elysiajs/cors";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

const app = new Elysia()
  .use(cors({ origin: ["http://localhost:3000"] }))
  .get("/", () => "Welcome to Smart Repair API")
  .get("/api/tickets", () => {
    return prisma.ticket.findMany({
      orderBy: { createdAt: "desc" },
    });
  })
  .get("/api/analytics", async () => {
    const total = await prisma.ticket.count();
    const done = await prisma.ticket.count({ where: { status: "done" } });
    const urgent = await prisma.ticket.count({ where: { priority: "urgent" } });
    const inProgress = await prisma.ticket.count({ where: { status: "in-progress" } });

    const todo = total - done - inProgress;

    // 为图表提供分布数据
    const distribution = [
      { name: "待处理", value: todo, fill: "#71717a" }, // zinc-500
      { name: "维修中", value: inProgress, fill: "#3b82f6" }, // blue-500
      { name: "已完成", value: done, fill: "#22c55e" }, // green-500
    ].filter(item => item.value > 0);

    return {
      total,
      done,
      urgent,
      inProgress,
      completionRate: total === 0 ? 0 : Math.round((done / total) * 100),
      distribution
    };
  })
  .post("/api/login", async ({ body }) => {
    const { username, password } = body;
    if (username === "admin" && password === "admin123") {
      return { success: true, token: "admin-jwt-token", role: "admin", name: "Admin" };
    }
    return new Response(JSON.stringify({ error: "账号或密码错误" }), { status: 401 });
  }, {
    body: t.Object({
      username: t.String(),
      password: t.String()
    })
  })
  .post("/api/tickets", async ({ body }) => {
    const { title, description } = body;

    const urgentKeywords = ["碎", "不亮", "冒烟", "坏"];
    const isUrgent = urgentKeywords.some(keyword => description.includes(keyword));
    const priority = isUrgent ? "urgent" : "normal";

    return prisma.ticket.create({
      data: {
        title,
        description,
        priority,
        status: "todo",
      },
    });
  }, {
    body: t.Object({
      title: t.String({ minLength: 1, error: "标题不能为空" }),
      description: t.String({ minLength: 1, error: "描述不能为空" })
    })
  })
  .patch("/api/tickets/:id", async ({ headers, set, params: { id }, body }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    const { status } = body;
    return prisma.ticket.update({
      where: { id: Number(id) },
      data: { status },
    });
  }, {
    body: t.Object({
      status: t.String()
    })
  })
  .delete("/api/tickets/clear-done", async ({ headers, set }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    return prisma.ticket.deleteMany({
      where: { status: "done" },
    });
  })
  .delete("/api/tickets/:id", async ({ headers, set, params: { id } }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    return prisma.ticket.delete({
      where: { id: Number(id) },
    });
  })
  .listen(8080);

console.log(
  ` Elysia is running at ${app.server?.hostname}:${app.server?.port}`
);

"use client";

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { AUTH_EVENT, Role, clearAuthProfile, refreshAuthFromServer } from '@/lib/auth';
import { ApiError, apiJson } from '@/lib/api';

interface Ticket {
  id: number;
  title: string;
  description: string;
  priority: 'urgent' | 'normal';
  status: 'todo' | 'in-progress' | 'done';
  createdAt: string;
  updatedAt: string;
}

type StatusFilter = 'all' | Ticket['status'];
type PriorityFilter = 'all' | Ticket['priority'];
type SortMode = 'newest' | 'oldest' | 'priority';

const VIEW_STORAGE_KEY = 'sr_board_view_v1';
const NOTE_STORAGE_KEY = 'sr_ticket_notes_v1';

export default function SmartRepairHub() {
  const router = useRouter();
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [priorityFilter, setPriorityFilter] = useState<PriorityFilter>('all');
  const [sortMode, setSortMode] = useState<SortMode>('newest');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<Ticket['priority']>('normal');
  const [autoPriorityEnabled, setAutoPriorityEnabled] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [role, setRole] = useState<Role | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [lastSnapshot, setLastSnapshot] = useState<Ticket[] | null>(null);
  const [activeTicketId, setActiveTicketId] = useState<number | null>(null);
  const [notesByTicketId, setNotesByTicketId] = useState<Record<number, string>>({});

  const canManageStatus = role === 'admin' || role === 'worker';
  const canDelete = role === 'admin';

  const activeTicket = useMemo(
    () => tickets.find((ticket) => ticket.id === activeTicketId) ?? null,
    [activeTicketId, tickets]
  );

  const checkAuth = async () => {
    const snapshot = await refreshAuthFromServer();
    setRole(snapshot.role);
  };

  const handleUnauthorized = useCallback(() => {
    clearAuthProfile();
    router.push('/login');
  }, [router]);

  const fetchPriorityMode = useCallback(async () => {
    try {
      const data = await apiJson<{ autoPriorityEnabled: boolean }>('/api/settings/priority-mode');
      setAutoPriorityEnabled(Boolean(data.autoPriorityEnabled));
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('加载系统设置失败，请稍后重试。');
      console.error('Error fetching priority mode:', error);
    }
  }, [handleUnauthorized]);

  const fetchTickets = useCallback(async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const params = new URLSearchParams();
      if (debouncedQuery.trim()) params.set('q', debouncedQuery.trim());
      if (statusFilter !== 'all') params.set('status', statusFilter);
      if (priorityFilter !== 'all') params.set('priority', priorityFilter);

      const queryString = params.toString();
      const data = await apiJson<Ticket[]>(`/api/tickets${queryString ? `?${queryString}` : ''}`);
      setTickets(data);
      setSelectedIds((prev) => prev.filter((id) => data.some((ticket) => ticket.id === id)));
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('加载工单失败，请检查网络或后端服务。');
      console.error('Error fetching tickets:', error);
    } finally {
      setIsLoading(false);
    }
  }, [debouncedQuery, statusFilter, priorityFilter, handleUnauthorized]);

  useEffect(() => {
    try {
      const rawViewState = localStorage.getItem(VIEW_STORAGE_KEY);
      if (rawViewState) {
        const parsed = JSON.parse(rawViewState) as {
          searchQuery?: string;
          statusFilter?: StatusFilter;
          priorityFilter?: PriorityFilter;
          sortMode?: SortMode;
        };
        setSearchQuery(parsed.searchQuery ?? '');
        setDebouncedQuery(parsed.searchQuery ?? '');
        setStatusFilter(parsed.statusFilter ?? 'all');
        setPriorityFilter(parsed.priorityFilter ?? 'all');
        setSortMode(parsed.sortMode ?? 'newest');
      }

      const rawNotes = localStorage.getItem(NOTE_STORAGE_KEY);
      if (rawNotes) {
        const parsedNotes = JSON.parse(rawNotes) as Record<string, string>;
        const normalized: Record<number, string> = {};
        Object.keys(parsedNotes).forEach((key) => {
          const numericId = Number(key);
          if (Number.isFinite(numericId)) {
            normalized[numericId] = parsedNotes[key];
          }
        });
        setNotesByTicketId(normalized);
      }
    } catch {
      // Ignore invalid local data and use defaults.
    }
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setDebouncedQuery(searchQuery);
    }, 300);

    return () => window.clearTimeout(timer);
  }, [searchQuery]);

  useEffect(() => {
    localStorage.setItem(
      VIEW_STORAGE_KEY,
      JSON.stringify({ searchQuery, statusFilter, priorityFilter, sortMode })
    );
  }, [searchQuery, statusFilter, priorityFilter, sortMode]);

  useEffect(() => {
    localStorage.setItem(NOTE_STORAGE_KEY, JSON.stringify(notesByTicketId));
  }, [notesByTicketId]);

  useEffect(() => {
    void fetchTickets();
  }, [fetchTickets]);

  useEffect(() => {
    const onAuthChanged = () => {
      void checkAuth();
      void fetchPriorityMode();
    };
    void checkAuth();
    void fetchPriorityMode();
    window.addEventListener(AUTH_EVENT, onAuthChanged);
    return () => window.removeEventListener(AUTH_EVENT, onAuthChanged);
  }, [fetchPriorityMode]);

  const handleSubmit = async () => {
    if (!title.trim() || !description.trim()) return;

    setIsSubmitting(true);
    setErrorMessage(null);
    try {
      await apiJson('/api/tickets', {
        method: 'POST',
        body: JSON.stringify({ title, description, priority }),
      });
      setTitle('');
      setDescription('');
      setPriority('normal');
      await fetchTickets();
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('提交报修失败，请稍后再试。');
      console.error('Error creating ticket:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: number) => {
    e.stopPropagation();
    if (!window.confirm('确定要删除这条报修记录吗？')) return;

    setErrorMessage(null);
    try {
      await apiJson(`/api/tickets/${id}`, {
        method: 'DELETE',
      });
      setTickets((prev) => prev.filter((ticket) => ticket.id !== id));
      setSelectedIds((prev) => prev.filter((ticketId) => ticketId !== id));
      if (activeTicketId === id) setActiveTicketId(null);
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('删除失败：当前账号没有权限或网络异常。');
      console.error('Error deleting ticket:', error);
    }
  };

  const handleClearDone = async () => {
    if (!window.confirm('确定要清空所有已完成的报修记录吗？')) return;

    setErrorMessage(null);
    try {
      await apiJson('/api/tickets/clear-done', {
        method: 'DELETE',
      });
      setTickets((prev) => prev.filter((ticket) => ticket.status !== 'done'));
      setSelectedIds((prev) => prev.filter((id) => tickets.find((ticket) => ticket.id === id)?.status !== 'done'));
      if (activeTicket && activeTicket.status === 'done') setActiveTicketId(null);
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('清空失败：权限不足或网络异常。');
      console.error('Error clearing done tickets:', error);
    }
  };

  const updateTicketStatus = async (ticketId: number, newStatus: Ticket['status']) => {
    try {
      await apiJson(`/api/tickets/${ticketId}`, {
        method: 'PATCH',
        body: JSON.stringify({ status: newStatus }),
      });
      return true;
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return false;
      }
      console.error('Error updating ticket status:', error);
      return false;
    }
  };

  const handleBatchMove = async (targetStatus: Ticket['status']) => {
    if (!canManageStatus || selectedIds.length === 0) return;

    const snapshot = [...tickets];
    setLastSnapshot(snapshot);
    setErrorMessage(null);

    setTickets((prev) =>
      prev.map((ticket) => (selectedIds.includes(ticket.id) ? { ...ticket, status: targetStatus } : ticket))
    );

    const results = await Promise.all(
      selectedIds.map((id) => updateTicketStatus(id, targetStatus))
    );

    if (results.some((success) => !success)) {
      setErrorMessage('部分工单更新失败，已自动回滚。');
      setTickets(snapshot);
      return;
    }

    setSelectedIds([]);
  };

  const handleUndoBatch = async () => {
    if (!lastSnapshot) return;

    const current = [...tickets];
    setTickets(lastSnapshot);
    const currentMap = new Map(current.map((ticket) => [ticket.id, ticket]));

    const rollbackPairs = lastSnapshot
      .map((oldTicket) => {
        const currentTicket = currentMap.get(oldTicket.id);
        if (!currentTicket || currentTicket.status === oldTicket.status) {
          return null;
        }
        return { id: oldTicket.id, status: oldTicket.status };
      })
      .filter((item): item is { id: number; status: Ticket['status'] } => Boolean(item));

    const results = await Promise.all(
      rollbackPairs.map((item) => updateTicketStatus(item.id, item.status))
    );

    if (results.some((ok) => !ok)) {
      setErrorMessage('撤销未完全成功，已重新同步列表。');
      await fetchTickets();
    }

    setLastSnapshot(null);
  };

  const handleDragStart = (e: React.DragEvent, id: number) => {
    e.dataTransfer.setData('ticketId', id.toString());
    setIsDragging(true);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = async (e: React.DragEvent, newStatus: Ticket['status']) => {
    e.preventDefault();
    setIsDragging(false);
    if (!canManageStatus) return;

    const ticketId = Number.parseInt(e.dataTransfer.getData('ticketId'), 10);
    if (!ticketId) return;

    const snapshot = [...tickets];
    setTickets((prev) =>
      prev.map((ticket) => (ticket.id === ticketId ? { ...ticket, status: newStatus } : ticket))
    );

    const ok = await updateTicketStatus(ticketId, newStatus);
    if (!ok) {
      setTickets(snapshot);
      setErrorMessage('状态更新失败，已恢复原状态。');
    }
  };

  const sortedTickets = useMemo(() => {
    const priorityWeight = (value: Ticket['priority']) => (value === 'urgent' ? 2 : 1);
    const next = [...tickets];

    next.sort((a, b) => {
      if (sortMode === 'priority') {
        const priorityDiff = priorityWeight(b.priority) - priorityWeight(a.priority);
        if (priorityDiff !== 0) return priorityDiff;
        return +new Date(b.createdAt) - +new Date(a.createdAt);
      }

      if (sortMode === 'oldest') {
        return +new Date(a.createdAt) - +new Date(b.createdAt);
      }

      return +new Date(b.createdAt) - +new Date(a.createdAt);
    });

    return next;
  }, [tickets, sortMode]);

  const stats = useMemo(() => {
    const todoCount = tickets.filter((ticket) => ticket.status === 'todo').length;
    const inProgressCount = tickets.filter((ticket) => ticket.status === 'in-progress').length;
    const doneCount = tickets.filter((ticket) => ticket.status === 'done').length;
    const urgentCount = tickets.filter((ticket) => ticket.priority === 'urgent').length;

    return { todoCount, inProgressCount, doneCount, urgentCount };
  }, [tickets]);

  const toggleSelectTicket = (ticketId: number) => {
    if (!canManageStatus) return;
    setSelectedIds((prev) =>
      prev.includes(ticketId) ? prev.filter((id) => id !== ticketId) : [...prev, ticketId]
    );
  };

  const resetFilters = () => {
    setSearchQuery('');
    setStatusFilter('all');
    setPriorityFilter('all');
    setSortMode('newest');
  };

  const updateNote = (ticketId: number, note: string) => {
    setNotesByTicketId((prev) => ({ ...prev, [ticketId]: note }));
  };

  const renderTickets = (status: Ticket['status']) => {
    const columnTickets = sortedTickets.filter((ticket) => ticket.status === status);

    if (columnTickets.length === 0) {
      return (
        <div className="mx-1 mt-2 flex flex-col items-center justify-center rounded-lg border-2 border-dashed border-zinc-800/50 bg-zinc-900/30 py-10 text-zinc-500">
          <svg className="mb-3 h-12 w-12 text-zinc-500 opacity-60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M4 10h16M9 10V7a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v3M6 10h12a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2Z" />
          </svg>
          <p className="text-xs font-medium">
            {debouncedQuery || statusFilter !== 'all' || priorityFilter !== 'all' ? '未找到相关工单' : '暂无数据'}
          </p>
        </div>
      );
    }

    return columnTickets.map((ticket) => {
      const isSelected = selectedIds.includes(ticket.id);
      const note = notesByTicketId[ticket.id] ?? '';

      return (
        <Card
          key={ticket.id}
          draggable={canManageStatus}
          onDragStart={(e) => canManageStatus && handleDragStart(e, ticket.id)}
          onDragEnd={() => canManageStatus && handleDragEnd()}
          onClick={() => setActiveTicketId(ticket.id)}
          className={`group relative mb-4 border bg-zinc-800 shadow-sm transition-colors ${
            canManageStatus ? 'cursor-grab active:cursor-grabbing hover:border-zinc-500' : 'cursor-pointer'
          } ${isSelected ? 'border-indigo-500/60 ring-1 ring-indigo-500/40' : 'border-zinc-700'}`}
        >
          {canManageStatus && (
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                toggleSelectTicket(ticket.id);
              }}
              className={`absolute left-2 top-2 z-10 rounded border px-1.5 py-0.5 text-[10px] transition-colors ${
                isSelected
                  ? 'border-indigo-400 bg-indigo-500/20 text-indigo-200'
                  : 'border-zinc-600 bg-zinc-900 text-zinc-400 hover:border-zinc-500 hover:text-zinc-200'
              }`}
              title={isSelected ? '取消多选' : '加入批量操作'}
            >
              {isSelected ? '已选' : '选择'}
            </button>
          )}

          {canDelete && (
            <button
              onClick={(e) => void handleDelete(e, ticket.id)}
              className="absolute right-2 top-2 z-10 rounded-full p-1 text-zinc-400 opacity-0 transition-all group-hover:opacity-100 hover:bg-zinc-700 hover:text-red-400"
              title="删除工单"
            >
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
          )}

          <CardHeader className="pb-2">
            <div className="flex items-start justify-between gap-2">
              <CardTitle className="flex-1 pr-6 text-sm font-medium text-zinc-100">{ticket.title}</CardTitle>
              <Badge
                variant={ticket.priority === 'urgent' ? 'destructive' : 'default'}
                className={
                  ticket.priority === 'urgent'
                    ? 'border-transparent bg-red-600 text-white hover:bg-red-700'
                    : 'border-transparent bg-zinc-600 text-white hover:bg-zinc-700'
                }
              >
                {ticket.priority === 'urgent' ? '紧急' : '普通'}
              </Badge>
            </div>
          </CardHeader>
          <CardContent>
            <p className="mb-2 line-clamp-2 text-xs text-zinc-400">{ticket.description}</p>
            <p className="mb-2 text-[10px] text-zinc-600">
              {new Date(ticket.createdAt).toLocaleString('zh-CN', {
                timeZone: 'Asia/Shanghai',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </p>
            {note && <p className="line-clamp-1 text-[10px] text-indigo-300/80">备注: {note}</p>}
          </CardContent>
        </Card>
      );
    });
  };

  return (
    <div className="min-h-screen bg-zinc-950 p-6 font-sans text-zinc-50">
      <header className="mb-6 border-b border-zinc-800 pb-4">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h1 className="bg-linear-to-r from-blue-400 to-indigo-500 bg-clip-text text-2xl font-extrabold text-transparent md:text-3xl">
              Smart Repair Hub
            </h1>
            <p className="mt-1 text-xs text-zinc-500">多选批量流转、筛选记忆和工单备注已启用。</p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="relative hidden sm:block">
              <svg className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              <Input
                placeholder="搜索报修工单..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="h-9 w-60 rounded-full border-zinc-700 bg-zinc-900 pl-8 text-xs text-zinc-100 focus-visible:ring-indigo-500"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="all">全部状态</option>
              <option value="todo">待处理</option>
              <option value="in-progress">维修中</option>
              <option value="done">已完成</option>
            </select>

            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value as PriorityFilter)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="all">全部优先级</option>
              <option value="urgent">紧急</option>
              <option value="normal">普通</option>
            </select>

            <select
              value={sortMode}
              onChange={(e) => setSortMode(e.target.value as SortMode)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="newest">最新优先</option>
              <option value="oldest">最早优先</option>
              <option value="priority">紧急优先</option>
            </select>

            <Button
              size="sm"
              variant="outline"
              className="border-zinc-700 bg-zinc-900 text-zinc-300 hover:bg-zinc-800"
              onClick={() => void fetchTickets()}
            >
              刷新
            </Button>

            <Button
              size="sm"
              variant="ghost"
              className="text-zinc-400 hover:bg-zinc-900 hover:text-zinc-100"
              onClick={resetFilters}
            >
              重置视图
            </Button>

            <div className="flex h-10 w-10 cursor-pointer items-center justify-center rounded-full border border-zinc-700 bg-zinc-800 text-zinc-300 shadow-inner transition-colors hover:bg-zinc-700">
              <span className="text-sm font-bold">{(role?.[0] ?? 'U').toUpperCase()}</span>
            </div>
          </div>
        </div>
      </header>

      <section className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">待处理</p>
          <p className="text-lg font-semibold text-zinc-100">{stats.todoCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">维修中</p>
          <p className="text-lg font-semibold text-blue-300">{stats.inProgressCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">已完成</p>
          <p className="text-lg font-semibold text-green-300">{stats.doneCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">紧急工单</p>
          <p className="text-lg font-semibold text-red-300">{stats.urgentCount}</p>
        </div>
      </section>

      {errorMessage && (
        <div className="mb-4 rounded-lg border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-200">
          {errorMessage}
        </div>
      )}

      {lastSnapshot && (
        <div className="mb-4 flex items-center justify-between rounded-lg border border-indigo-500/30 bg-indigo-500/10 px-4 py-2 text-sm text-indigo-200">
          <span>批量操作已完成。</span>
          <Button size="sm" variant="ghost" className="h-7 px-2 text-indigo-100 hover:bg-indigo-500/20" onClick={() => void handleUndoBatch()}>
            撤销
          </Button>
        </div>
      )}

      <main className="flex h-full flex-col gap-6 lg:flex-row">
        <section className="flex w-full flex-col gap-4 lg:w-1/4">
          <div className="rounded-xl border border-zinc-800 bg-zinc-900 p-6 shadow-md">
            <h2 className="mb-4 text-lg font-bold text-zinc-100 md:text-xl">一键报修</h2>

            <div className="mb-6 flex flex-col gap-4">
              <div>
                <label className="mb-1 block text-xs text-zinc-400">问题简述</label>
                <Input
                  placeholder="例如：实训室电脑蓝屏"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="border-zinc-700 bg-zinc-950 text-zinc-100"
                />
              </div>
              <div>
                <label className="mb-1 block text-xs text-zinc-400">详细描述</label>
                <Textarea
                  placeholder="请填写故障现象、地点和影响范围"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.ctrlKey && e.key === 'Enter') {
                      e.preventDefault();
                      void handleSubmit();
                    }
                  }}
                  className="h-24 resize-none border-zinc-700 bg-zinc-950 text-zinc-100"
                />
              </div>
              {!autoPriorityEnabled ? (
                <div>
                  <label className="mb-1 block text-xs text-zinc-400">优先级</label>
                  <select
                    value={priority}
                    onChange={(e) => setPriority(e.target.value as Ticket['priority'])}
                    className="h-10 w-full rounded-md border border-zinc-700 bg-zinc-950 px-3 text-sm text-zinc-200"
                  >
                    <option value="normal">普通</option>
                    <option value="urgent">紧急</option>
                  </select>
                </div>
              ) : (
                <p className="text-xs text-zinc-500">当前由系统自动判定优先级（可在系统设置中切换为手动）。</p>
              )}
            </div>

            <Button
              size="lg"
              onClick={() => void handleSubmit()}
              disabled={isSubmitting || !title.trim() || !description.trim()}
              className="w-full bg-indigo-600 font-semibold text-white shadow-lg shadow-indigo-500/20 transition-all hover:bg-indigo-500 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSubmitting ? '正在提交...' : '立即提交报修'}
            </Button>
            <p className="mt-2 text-[11px] text-zinc-500">快捷键: 在描述框按 Ctrl + Enter 快速提交</p>
          </div>

          {canManageStatus && (
            <div className="rounded-xl border border-zinc-800 bg-zinc-900 p-4">
              <p className="mb-2 text-xs text-zinc-400">批量操作 ({selectedIds.length})</p>
              <div className="grid grid-cols-3 gap-2">
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('todo')} disabled={selectedIds.length === 0}>
                  待处理
                </Button>
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('in-progress')} disabled={selectedIds.length === 0}>
                  维修中
                </Button>
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('done')} disabled={selectedIds.length === 0}>
                  已完成
                </Button>
              </div>
            </div>
          )}
        </section>

        <section className="grid h-full w-full min-h-150 grid-cols-1 gap-6 pb-10 md:grid-cols-3 lg:w-3/4">
          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'todo')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-zinc-700/80' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-zinc-500 drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]"></span>
                待处理
              </h3>
              <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.todoCount}</span>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2">{isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTickets('todo')}</div>
          </div>

          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'in-progress')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-blue-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-blue-500 drop-shadow-[0_0_8px_rgba(59,130,246,0.8)]"></span>
                维修中
              </h3>
              <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.inProgressCount}</span>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2">{isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTickets('in-progress')}</div>
          </div>

          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'done')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-green-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-green-500 drop-shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                已完成
              </h3>
              <div className="flex items-center gap-2">
                <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.doneCount}</span>
                {canDelete && tickets.some((ticket) => ticket.status === 'done') && (
                  <button
                    onClick={() => void handleClearDone()}
                    className="rounded p-1.5 text-xs text-zinc-500 opacity-70 transition-colors hover:bg-zinc-800 hover:text-red-400 hover:opacity-100"
                    title="清空所有已完成工单"
                  >
                    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2">{isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTickets('done')}</div>
          </div>
        </section>
      </main>

      {activeTicket && (
        <div className="fixed inset-0 z-40 flex items-end justify-center bg-black/60 p-4 sm:items-center" onClick={() => setActiveTicketId(null)}>
          <div className="w-full max-w-xl rounded-xl border border-zinc-700 bg-zinc-900 p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-start justify-between gap-3">
              <div>
                <h3 className="text-lg font-semibold text-zinc-100">{activeTicket.title}</h3>
                <p className="mt-1 text-xs text-zinc-500">工单 #{activeTicket.id}</p>
              </div>
              <Button size="sm" variant="ghost" className="text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200" onClick={() => setActiveTicketId(null)}>
                关闭
              </Button>
            </div>

            <div className="mb-4 grid grid-cols-3 gap-2 text-xs">
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">状态: {activeTicket.status}</div>
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">优先级: {activeTicket.priority}</div>
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">更新时间: {new Date(activeTicket.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })}</div>
            </div>

            <p className="mb-4 rounded-lg border border-zinc-800 bg-zinc-950 p-3 text-sm text-zinc-300">{activeTicket.description}</p>

            <label className="mb-1 block text-xs text-zinc-400">个人备注 (仅本地保存)</label>
            <Textarea
              value={notesByTicketId[activeTicket.id] ?? ''}
              onChange={(e) => updateNote(activeTicket.id, e.target.value)}
              placeholder="例如：已联系机房管理员，等待配件到货"
              className="h-24 resize-none border-zinc-700 bg-zinc-950 text-zinc-100"
            />
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, {
  useState,
  useEffect,
  useCallback,
  useMemo,
  useDeferredValue,
  useRef,
} from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { AUTH_EVENT, Role, clearAuthProfile, refreshAuthFromServer } from '@/lib/auth';
import { ApiError, apiJson } from '@/lib/api';
import { TicketCard } from '@/components/tickets/TicketCard';

interface Ticket {
  id: number;
  title: string;
  description: string;
  priority: 'urgent' | 'normal';
  status: 'todo' | 'in-progress' | 'done';
  createdAt: string;
  updatedAt: string;
}

type StatusFilter = 'all' | Ticket['status'];
type PriorityFilter = 'all' | Ticket['priority'];
type SortMode = 'newest' | 'oldest' | 'priority';
type StatusKey = Ticket['status'];

const VIEW_STORAGE_KEY = 'sr_board_view_v1';
const NOTE_STORAGE_KEY = 'sr_ticket_notes_v1';
const PAGE_SIZE = 25;

function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName.toLowerCase();
  return tag === 'input' || tag === 'textarea' || tag === 'select' || target.isContentEditable;
}

export default function SmartRepairHub() {
  const router = useRouter();
  const searchInputRef = useRef<HTMLInputElement>(null);

  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const deferredSearchQuery = useDeferredValue(searchQuery);
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [priorityFilter, setPriorityFilter] = useState<PriorityFilter>('all');
  const [sortMode, setSortMode] = useState<SortMode>('newest');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<Ticket['priority']>('normal');
  const [autoPriorityEnabled, setAutoPriorityEnabled] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [role, setRole] = useState<Role | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [lastSnapshot, setLastSnapshot] = useState<Ticket[] | null>(null);
  const [activeTicketId, setActiveTicketId] = useState<number | null>(null);
  const [notesByTicketId, setNotesByTicketId] = useState<Record<number, string>>({});
  const [visibleCountByStatus, setVisibleCountByStatus] = useState<Record<StatusKey, number>>({
    todo: PAGE_SIZE,
    'in-progress': PAGE_SIZE,
    done: PAGE_SIZE,
  });

  const canManageStatus = role === 'admin' || role === 'worker';
  const canDelete = role === 'admin';

  const activeTicket = useMemo(
    () => tickets.find((ticket) => ticket.id === activeTicketId) ?? null,
    [activeTicketId, tickets]
  );

  const checkAuth = async () => {
    const snapshot = await refreshAuthFromServer();
    setRole(snapshot.role);
  };

  const handleUnauthorized = useCallback(() => {
    clearAuthProfile();
    router.push('/login');
  }, [router]);

  const fetchPriorityMode = useCallback(async () => {
    try {
      const data = await apiJson<{ autoPriorityEnabled: boolean }>('/api/settings/priority-mode');
      setAutoPriorityEnabled(Boolean(data.autoPriorityEnabled));
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('加载系统设置失败，请稍后重试。');
      console.error('Error fetching priority mode:', error);
    }
  }, [handleUnauthorized]);

  const fetchTickets = useCallback(async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const params = new URLSearchParams();
      if (debouncedQuery.trim()) params.set('q', debouncedQuery.trim());
      if (statusFilter !== 'all') params.set('status', statusFilter);
      if (priorityFilter !== 'all') params.set('priority', priorityFilter);

      const queryString = params.toString();
      const data = await apiJson<Ticket[]>(`/api/tickets${queryString ? `?${queryString}` : ''}`);
      setTickets(data);
      setSelectedIds((prev) => prev.filter((id) => data.some((ticket) => ticket.id === id)));
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('加载工单失败，请检查网络或后端服务。');
      console.error('Error fetching tickets:', error);
    } finally {
      setIsLoading(false);
    }
  }, [debouncedQuery, statusFilter, priorityFilter, handleUnauthorized]);

  const updateTicketStatus = useCallback(
    async (ticketId: number, newStatus: Ticket['status']) => {
      try {
        await apiJson(`/api/tickets/${ticketId}`, {
          method: 'PATCH',
          body: JSON.stringify({ status: newStatus }),
        });
        return true;
      } catch (error) {
        if (error instanceof ApiError && error.status === 401) {
          handleUnauthorized();
          return false;
        }
        console.error('Error updating ticket status:', error);
        return false;
      }
    },
    [handleUnauthorized]
  );

  useEffect(() => {
    try {
      const rawViewState = localStorage.getItem(VIEW_STORAGE_KEY);
      if (rawViewState) {
        const parsed = JSON.parse(rawViewState) as {
          searchQuery?: string;
          statusFilter?: StatusFilter;
          priorityFilter?: PriorityFilter;
          sortMode?: SortMode;
        };
        setSearchQuery(parsed.searchQuery ?? '');
        setDebouncedQuery(parsed.searchQuery ?? '');
        setStatusFilter(parsed.statusFilter ?? 'all');
        setPriorityFilter(parsed.priorityFilter ?? 'all');
        setSortMode(parsed.sortMode ?? 'newest');
      }

      const params = new URLSearchParams(window.location.search);
      const status = params.get('status');
      const priorityFromUrl = params.get('priority');
      if (status === 'todo' || status === 'in-progress' || status === 'done') {
        setStatusFilter(status);
      }
      if (priorityFromUrl === 'urgent' || priorityFromUrl === 'normal') {
        setPriorityFilter(priorityFromUrl);
      }

      const rawNotes = localStorage.getItem(NOTE_STORAGE_KEY);
      if (rawNotes) {
        const parsedNotes = JSON.parse(rawNotes) as Record<string, string>;
        const normalized: Record<number, string> = {};
        Object.keys(parsedNotes).forEach((key) => {
          const numericId = Number(key);
          if (Number.isFinite(numericId)) {
            normalized[numericId] = parsedNotes[key];
          }
        });
        setNotesByTicketId(normalized);
      }
    } catch {
      // Ignore invalid local data and use defaults.
    }
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setDebouncedQuery(deferredSearchQuery);
    }, 250);

    return () => window.clearTimeout(timer);
  }, [deferredSearchQuery]);

  useEffect(() => {
    localStorage.setItem(
      VIEW_STORAGE_KEY,
      JSON.stringify({ searchQuery, statusFilter, priorityFilter, sortMode })
    );
  }, [searchQuery, statusFilter, priorityFilter, sortMode]);

  useEffect(() => {
    localStorage.setItem(NOTE_STORAGE_KEY, JSON.stringify(notesByTicketId));
  }, [notesByTicketId]);

  useEffect(() => {
    setVisibleCountByStatus({ todo: PAGE_SIZE, 'in-progress': PAGE_SIZE, done: PAGE_SIZE });
  }, [debouncedQuery, statusFilter, priorityFilter, sortMode]);

  useEffect(() => {
    void fetchTickets();
  }, [fetchTickets]);

  useEffect(() => {
    const onAuthChanged = () => {
      void checkAuth();
      void fetchPriorityMode();
    };
    void checkAuth();
    void fetchPriorityMode();
    window.addEventListener(AUTH_EVENT, onAuthChanged);
    return () => window.removeEventListener(AUTH_EVENT, onAuthChanged);
  }, [fetchPriorityMode]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === '/' && !isEditableTarget(event.target)) {
        event.preventDefault();
        searchInputRef.current?.focus();
        return;
      }

      if (event.key === 'Escape') {
        setActiveTicketId(null);
        return;
      }

      if (isEditableTarget(event.target)) {
        return;
      }

      if (event.key.toLowerCase() === 'r' && !event.metaKey && !event.ctrlKey) {
        event.preventDefault();
        void fetchTickets();
        return;
      }

      if (event.ctrlKey && event.shiftKey) {
        if (event.key === '1') {
          event.preventDefault();
          void handleBatchMove('todo');
        }
        if (event.key === '2') {
          event.preventDefault();
          void handleBatchMove('in-progress');
        }
        if (event.key === '3') {
          event.preventDefault();
          void handleBatchMove('done');
        }
        return;
      }

      if (event.key.toLowerCase() === 'j' || event.key.toLowerCase() === 'k') {
        event.preventDefault();
        const ids = sortedTickets.map((ticket) => ticket.id);
        if (ids.length === 0) return;

        const currentIndex = activeTicketId ? ids.indexOf(activeTicketId) : -1;
        if (event.key.toLowerCase() === 'j') {
          const nextIndex = currentIndex < ids.length - 1 ? currentIndex + 1 : 0;
          setActiveTicketId(ids[nextIndex]);
        } else {
          const prevIndex = currentIndex > 0 ? currentIndex - 1 : ids.length - 1;
          setActiveTicketId(ids[prevIndex]);
        }
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [activeTicketId, fetchTickets, sortedTickets]);

  const handleSubmit = async () => {
    if (!title.trim() || !description.trim()) return;

    setIsSubmitting(true);
    setErrorMessage(null);
    try {
      await apiJson('/api/tickets', {
        method: 'POST',
        body: JSON.stringify({ title, description, priority }),
      });
      setTitle('');
      setDescription('');
      setPriority('normal');
      await fetchTickets();
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('提交报修失败，请稍后再试。');
      console.error('Error creating ticket:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = useCallback(
    async (e: React.MouseEvent, id: number) => {
      e.stopPropagation();
      if (!window.confirm('确定要删除这条报修记录吗？')) return;

      setErrorMessage(null);
      try {
        await apiJson(`/api/tickets/${id}`, { method: 'DELETE' });
        setTickets((prev) => prev.filter((ticket) => ticket.id !== id));
        setSelectedIds((prev) => prev.filter((ticketId) => ticketId !== id));
        if (activeTicketId === id) setActiveTicketId(null);
      } catch (error) {
        if (error instanceof ApiError && error.status === 401) {
          handleUnauthorized();
          return;
        }
        setErrorMessage('删除失败：当前账号没有权限或网络异常。');
        console.error('Error deleting ticket:', error);
      }
    },
    [activeTicketId, handleUnauthorized]
  );

  const handleClearDone = async () => {
    if (!window.confirm('确定要清空所有已完成的报修记录吗？')) return;

    const doneIds = new Set(tickets.filter((ticket) => ticket.status === 'done').map((ticket) => ticket.id));
    setErrorMessage(null);
    try {
      await apiJson('/api/tickets/clear-done', {
        method: 'DELETE',
      });
      setTickets((prev) => prev.filter((ticket) => ticket.status !== 'done'));
      setSelectedIds((prev) => prev.filter((id) => !doneIds.has(id)));
      if (activeTicket && activeTicket.status === 'done') setActiveTicketId(null);
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        handleUnauthorized();
        return;
      }
      setErrorMessage('清空失败：权限不足或网络异常。');
      console.error('Error clearing done tickets:', error);
    }
  };

  const handleBatchMove = useCallback(
    async (targetStatus: Ticket['status']) => {
      if (!canManageStatus || selectedIds.length === 0) return;

      const snapshot = [...tickets];
      setLastSnapshot(snapshot);
      setErrorMessage(null);

      setTickets((prev) =>
        prev.map((ticket) =>
          selectedIds.includes(ticket.id) ? { ...ticket, status: targetStatus } : ticket
        )
      );

      const results = await Promise.all(selectedIds.map((id) => updateTicketStatus(id, targetStatus)));

      if (results.some((success) => !success)) {
        setErrorMessage('部分工单更新失败，已自动回滚。');
        setTickets(snapshot);
        return;
      }

      setSelectedIds([]);
    },
    [canManageStatus, selectedIds, tickets, updateTicketStatus]
  );

  const handleUndoBatch = async () => {
    if (!lastSnapshot) return;

    const current = [...tickets];
    setTickets(lastSnapshot);
    const currentMap = new Map(current.map((ticket) => [ticket.id, ticket]));

    const rollbackPairs = lastSnapshot
      .map((oldTicket) => {
        const currentTicket = currentMap.get(oldTicket.id);
        if (!currentTicket || currentTicket.status === oldTicket.status) {
          return null;
        }
        return { id: oldTicket.id, status: oldTicket.status };
      })
      .filter((item): item is { id: number; status: Ticket['status'] } => Boolean(item));

    const results = await Promise.all(rollbackPairs.map((item) => updateTicketStatus(item.id, item.status)));

    if (results.some((ok) => !ok)) {
      setErrorMessage('撤销未完全成功，已重新同步列表。');
      await fetchTickets();
    }

    setLastSnapshot(null);
  };

  const handleDragStart = useCallback((e: React.DragEvent, id: number) => {
    e.dataTransfer.setData('ticketId', id.toString());
    setIsDragging(true);
  }, []);

  const handleDragEnd = useCallback(() => {
    setIsDragging(false);
  }, []);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = async (e: React.DragEvent, newStatus: Ticket['status']) => {
    e.preventDefault();
    setIsDragging(false);
    if (!canManageStatus) return;

    const ticketId = Number.parseInt(e.dataTransfer.getData('ticketId'), 10);
    if (!ticketId) return;

    const snapshot = [...tickets];
    setTickets((prev) =>
      prev.map((ticket) => (ticket.id === ticketId ? { ...ticket, status: newStatus } : ticket))
    );

    const ok = await updateTicketStatus(ticketId, newStatus);
    if (!ok) {
      setTickets(snapshot);
      setErrorMessage('状态更新失败，已恢复原状态。');
    }
  };

  const sortedTickets = useMemo(() => {
    const priorityWeight = (value: Ticket['priority']) => (value === 'urgent' ? 2 : 1);
    const next = [...tickets];

    next.sort((a, b) => {
      if (sortMode === 'priority') {
        const priorityDiff = priorityWeight(b.priority) - priorityWeight(a.priority);
        if (priorityDiff !== 0) return priorityDiff;
        return +new Date(b.createdAt) - +new Date(a.createdAt);
      }

      if (sortMode === 'oldest') {
        return +new Date(a.createdAt) - +new Date(b.createdAt);
      }

      return +new Date(b.createdAt) - +new Date(a.createdAt);
    });

    return next;
  }, [tickets, sortMode]);

  const todoTickets = useMemo(
    () => sortedTickets.filter((ticket) => ticket.status === 'todo'),
    [sortedTickets]
  );
  const inProgressTickets = useMemo(
    () => sortedTickets.filter((ticket) => ticket.status === 'in-progress'),
    [sortedTickets]
  );
  const doneTickets = useMemo(
    () => sortedTickets.filter((ticket) => ticket.status === 'done'),
    [sortedTickets]
  );

  const stats = useMemo(() => {
    const todoCount = todoTickets.length;
    const inProgressCount = inProgressTickets.length;
    const doneCount = doneTickets.length;
    const urgentCount = tickets.filter((ticket) => ticket.priority === 'urgent').length;

    return { todoCount, inProgressCount, doneCount, urgentCount };
  }, [todoTickets.length, inProgressTickets.length, doneTickets.length, tickets]);

  const toggleSelectTicket = useCallback(
    (ticketId: number) => {
      if (!canManageStatus) return;
      setSelectedIds((prev) =>
        prev.includes(ticketId) ? prev.filter((id) => id !== ticketId) : [...prev, ticketId]
      );
    },
    [canManageStatus]
  );

  const resetFilters = () => {
    setSearchQuery('');
    setStatusFilter('all');
    setPriorityFilter('all');
    setSortMode('newest');
  };

  const updateNote = (ticketId: number, note: string) => {
    setNotesByTicketId((prev) => ({ ...prev, [ticketId]: note }));
  };

  const handleColumnScroll = (status: StatusKey, e: React.UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget;
    const nearBottom = target.scrollHeight - target.scrollTop - target.clientHeight < 160;
    if (!nearBottom) return;

    setVisibleCountByStatus((prev) => ({
      ...prev,
      [status]: prev[status] + PAGE_SIZE,
    }));
  };

  const renderTicketList = (status: StatusKey, columnTickets: Ticket[]) => {
    const visibleTickets = columnTickets.slice(0, visibleCountByStatus[status]);

    if (columnTickets.length === 0) {
      return (
        <div className="mx-1 mt-2 flex flex-col items-center justify-center rounded-lg border-2 border-dashed border-zinc-800/50 bg-zinc-900/30 py-10 text-zinc-500">
          <svg className="mb-3 h-12 w-12 text-zinc-500 opacity-60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M4 10h16M9 10V7a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v3M6 10h12a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2Z" />
          </svg>
          <p className="text-xs font-medium">
            {debouncedQuery || statusFilter !== 'all' || priorityFilter !== 'all' ? '未找到相关工单' : '暂无数据'}
          </p>
        </div>
      );
    }

    return (
      <>
        {visibleTickets.map((ticket) => (
          <TicketCard
            key={ticket.id}
            ticket={ticket}
            canManageStatus={canManageStatus}
            canDelete={canDelete}
            isSelected={selectedIds.includes(ticket.id)}
            note={notesByTicketId[ticket.id] ?? ''}
            onOpen={setActiveTicketId}
            onToggleSelect={toggleSelectTicket}
            onDelete={(e, id) => {
              void handleDelete(e, id);
            }}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
          />
        ))}
        {visibleTickets.length < columnTickets.length && (
          <p className="py-2 text-center text-[11px] text-zinc-500">向下滚动加载更多...</p>
        )}
      </>
    );
  };

  return (
    <div className="min-h-screen bg-zinc-950 p-6 font-sans text-zinc-50">
      <header className="mb-6 border-b border-zinc-800 pb-4">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h1 className="bg-linear-to-r from-blue-400 to-indigo-500 bg-clip-text text-2xl font-extrabold text-transparent md:text-3xl">
              Smart Repair Hub
            </h1>
            <p className="mt-1 text-xs text-zinc-500">
              快捷键: / 搜索, R 刷新, J/K 切换工单, Ctrl+Shift+1/2/3 批量改状态
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="relative hidden sm:block">
              <svg className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              <Input
                ref={searchInputRef}
                placeholder="搜索报修工单..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="h-9 w-60 rounded-full border-zinc-700 bg-zinc-900 pl-8 text-xs text-zinc-100 focus-visible:ring-indigo-500"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="all">全部状态</option>
              <option value="todo">待处理</option>
              <option value="in-progress">维修中</option>
              <option value="done">已完成</option>
            </select>

            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value as PriorityFilter)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="all">全部优先级</option>
              <option value="urgent">紧急</option>
              <option value="normal">普通</option>
            </select>

            <select
              value={sortMode}
              onChange={(e) => setSortMode(e.target.value as SortMode)}
              className="h-9 rounded-md border border-zinc-700 bg-zinc-900 px-2 text-xs text-zinc-200"
            >
              <option value="newest">最新优先</option>
              <option value="oldest">最早优先</option>
              <option value="priority">紧急优先</option>
            </select>

            <Button
              size="sm"
              variant="outline"
              className="border-zinc-700 bg-zinc-900 text-zinc-300 hover:bg-zinc-800"
              onClick={() => void fetchTickets()}
            >
              刷新
            </Button>

            <Button
              size="sm"
              variant="ghost"
              className="text-zinc-400 hover:bg-zinc-900 hover:text-zinc-100"
              onClick={resetFilters}
            >
              重置视图
            </Button>

            <div className="flex h-10 w-10 cursor-pointer items-center justify-center rounded-full border border-zinc-700 bg-zinc-800 text-zinc-300 shadow-inner transition-colors hover:bg-zinc-700">
              <span className="text-sm font-bold">{(role?.[0] ?? 'U').toUpperCase()}</span>
            </div>
          </div>
        </div>
      </header>

      <section className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">待处理</p>
          <p className="text-lg font-semibold text-zinc-100">{stats.todoCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">维修中</p>
          <p className="text-lg font-semibold text-blue-300">{stats.inProgressCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">已完成</p>
          <p className="text-lg font-semibold text-green-300">{stats.doneCount}</p>
        </div>
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2">
          <p className="text-xs text-zinc-500">紧急工单</p>
          <p className="text-lg font-semibold text-red-300">{stats.urgentCount}</p>
        </div>
      </section>

      {errorMessage && (
        <div className="mb-4 rounded-lg border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-200">
          {errorMessage}
        </div>
      )}

      {lastSnapshot && (
        <div className="mb-4 flex items-center justify-between rounded-lg border border-indigo-500/30 bg-indigo-500/10 px-4 py-2 text-sm text-indigo-200">
          <span>批量操作已完成。</span>
          <Button
            size="sm"
            variant="ghost"
            className="h-7 px-2 text-indigo-100 hover:bg-indigo-500/20"
            onClick={() => void handleUndoBatch()}
          >
            撤销
          </Button>
        </div>
      )}

      <main className="flex h-full flex-col gap-6 lg:flex-row">
        <section className="flex w-full flex-col gap-4 lg:w-1/4">
          <div className="rounded-xl border border-zinc-800 bg-zinc-900 p-6 shadow-md">
            <h2 className="mb-4 text-lg font-bold text-zinc-100 md:text-xl">一键报修</h2>

            <div className="mb-6 flex flex-col gap-4">
              <div>
                <label className="mb-1 block text-xs text-zinc-400">问题简述</label>
                <Input
                  placeholder="例如：实训室电脑蓝屏"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="border-zinc-700 bg-zinc-950 text-zinc-100"
                />
              </div>
              <div>
                <label className="mb-1 block text-xs text-zinc-400">详细描述</label>
                <Textarea
                  placeholder="请填写故障现象、地点和影响范围"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.ctrlKey && e.key === 'Enter') {
                      e.preventDefault();
                      void handleSubmit();
                    }
                  }}
                  className="h-24 resize-none border-zinc-700 bg-zinc-950 text-zinc-100"
                />
              </div>
              {!autoPriorityEnabled ? (
                <div>
                  <label className="mb-1 block text-xs text-zinc-400">优先级</label>
                  <select
                    value={priority}
                    onChange={(e) => setPriority(e.target.value as Ticket['priority'])}
                    className="h-10 w-full rounded-md border border-zinc-700 bg-zinc-950 px-3 text-sm text-zinc-200"
                  >
                    <option value="normal">普通</option>
                    <option value="urgent">紧急</option>
                  </select>
                </div>
              ) : (
                <p className="text-xs text-zinc-500">当前由系统自动判定优先级（可在系统设置中切换为手动）。</p>
              )}
            </div>

            <Button
              size="lg"
              onClick={() => void handleSubmit()}
              disabled={isSubmitting || !title.trim() || !description.trim()}
              className="w-full bg-indigo-600 font-semibold text-white shadow-lg shadow-indigo-500/20 transition-all hover:bg-indigo-500 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSubmitting ? '正在提交...' : '立即提交报修'}
            </Button>
            <p className="mt-2 text-[11px] text-zinc-500">快捷键: 在描述框按 Ctrl + Enter 快速提交</p>
          </div>

          {canManageStatus ? (
            <div className="rounded-xl border border-zinc-800 bg-zinc-900 p-4">
              <p className="mb-2 text-xs text-zinc-400">批量操作 ({selectedIds.length})</p>
              <div className="grid grid-cols-3 gap-2">
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('todo')} disabled={selectedIds.length === 0}>
                  待处理
                </Button>
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('in-progress')} disabled={selectedIds.length === 0}>
                  维修中
                </Button>
                <Button size="sm" variant="outline" className="border-zinc-700 bg-zinc-900 text-zinc-200 hover:bg-zinc-800" onClick={() => void handleBatchMove('done')} disabled={selectedIds.length === 0}>
                  已完成
                </Button>
              </div>
            </div>
          ) : (
            <div className="rounded-xl border border-amber-500/20 bg-amber-500/5 p-4 text-xs text-amber-200">
              当前账号只有查看权限，不能批量流转工单。
            </div>
          )}
        </section>

        <section className="grid h-full w-full min-h-150 grid-cols-1 gap-6 pb-10 md:grid-cols-3 lg:w-3/4">
          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'todo')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-zinc-700/80' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-zinc-500 drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]"></span>
                待处理
              </h3>
              <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.todoCount}</span>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2" onScroll={(e) => handleColumnScroll('todo', e)}>
              {isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTicketList('todo', todoTickets)}
            </div>
          </div>

          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'in-progress')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-blue-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-blue-500 drop-shadow-[0_0_8px_rgba(59,130,246,0.8)]"></span>
                维修中
              </h3>
              <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.inProgressCount}</span>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2" onScroll={(e) => handleColumnScroll('in-progress', e)}>
              {isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTicketList('in-progress', inProgressTickets)}
            </div>
          </div>

          <div
            onDragOver={handleDragOver}
            onDrop={(e) => void handleDrop(e, 'done')}
            className={`flex h-full max-h-[80vh] flex-col rounded-xl border bg-zinc-900/80 p-4 shadow-inner transition-colors ${isDragging ? 'border-green-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="sticky top-0 z-10 mb-4 flex items-center justify-between bg-transparent px-1">
              <h3 className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-300">
                <span className="inline-block h-2 w-2 rounded-full bg-green-500 drop-shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                已完成
              </h3>
              <div className="flex items-center gap-2">
                <span className="rounded-full bg-zinc-800 px-2 py-0.5 text-xs font-medium text-zinc-500">{stats.doneCount}</span>
                {canDelete && tickets.some((ticket) => ticket.status === 'done') && (
                  <button
                    onClick={() => void handleClearDone()}
                    className="rounded p-1.5 text-xs text-zinc-500 opacity-70 transition-colors hover:bg-zinc-800 hover:text-red-400 hover:opacity-100"
                    title="清空所有已完成工单"
                  >
                    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
            <div className="custom-scrollbar flex flex-1 flex-col overflow-y-auto pr-1 pb-2" onScroll={(e) => handleColumnScroll('done', e)}>
              {isLoading ? <p className="py-8 text-center text-xs text-zinc-500">正在加载...</p> : renderTicketList('done', doneTickets)}
            </div>
          </div>
        </section>
      </main>

      {activeTicket && (
        <div className="fixed inset-0 z-40 flex items-end justify-center bg-black/60 p-4 sm:items-center" onClick={() => setActiveTicketId(null)}>
          <div className="w-full max-w-xl rounded-xl border border-zinc-700 bg-zinc-900 p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-start justify-between gap-3">
              <div>
                <h3 className="text-lg font-semibold text-zinc-100">{activeTicket.title}</h3>
                <p className="mt-1 text-xs text-zinc-500">工单 #{activeTicket.id}</p>
              </div>
              <Button size="sm" variant="ghost" className="text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200" onClick={() => setActiveTicketId(null)}>
                关闭
              </Button>
            </div>

            <div className="mb-4 grid grid-cols-3 gap-2 text-xs">
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">状态: {activeTicket.status}</div>
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">优先级: {activeTicket.priority}</div>
              <div className="rounded border border-zinc-700 bg-zinc-950 px-2 py-1 text-zinc-400">更新时间: {new Date(activeTicket.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })}</div>
            </div>

            <p className="mb-4 rounded-lg border border-zinc-800 bg-zinc-950 p-3 text-sm text-zinc-300">{activeTicket.description}</p>

            <label className="mb-1 block text-xs text-zinc-400">个人备注 (仅本地保存)</label>
            <Textarea
              value={notesByTicketId[activeTicket.id] ?? ''}
              onChange={(e) => updateNote(activeTicket.id, e.target.value)}
              placeholder="例如：已联系机房管理员，等待配件到货"
              className="h-24 resize-none border-zinc-700 bg-zinc-950 text-zinc-100"
            />
          </div>
        </div>
      )}
    </div>
  );
}
